package com.rainsleep.app;

import android.app.*;import android.content.*;import android.media.*;import android.os.*;
import java.util.concurrent.*;

public class RainService extends Service {
 public static volatile boolean running=false,playing=false;
 public static volatile long deadline=0;public static volatile int minutes=0;
 public static volatile float volume=1f;public static volatile String track="rain-jungle";
 public static volatile boolean mixAudio=false;
 static final String[] IDS={"rain-jungle","waves","stream","forest-night","campfire","sleep-music","binaural"};
 static final String[] NAMES={"热带雨林","海浪","溪流","夜间虫鸣","篝火","助眠音乐","脑波助眠"};
 AudioTrack player,retiring;long fadeStarted=0;int generation=0;boolean destroyed=false;float duck=1;
 AudioManager manager;AudioFocusRequest focus;android.media.session.MediaSession session;PowerManager.WakeLock wake;
 Handler handler=new Handler(Looper.getMainLooper());ExecutorService loader=Executors.newSingleThreadExecutor();
 public static boolean validTrack(String id){return java.util.Arrays.asList(IDS).contains(id);}
 public void onCreate(){super.onCreate();running=true;manager=(AudioManager)getSystemService(AUDIO_SERVICE);android.content.SharedPreferences prefs=getSharedPreferences("playback",0);mixAudio=prefs.getBoolean("mixAudio",false);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("rain","自然入眠播放",NotificationManager.IMPORTANCE_LOW));session=new android.media.session.MediaSession(this,"NatureSleep");session.setCallback(new android.media.session.MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pausePlayback();}public void onStop(){pausePlayback();}public void onSkipToNext(){changeTrack(1);}public void onSkipToPrevious(){changeTrack(-1);}public void onCustomAction(String action,Bundle extras){if("timer".equals(action))cycleTimer();}});session.setActive(true);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"NatureSleep:Audio");wake.setReferenceCounted(false);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT)pausePlayback();else duck=change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK?.2f:1;}).build();}
 PendingIntent serviceAction(int request,String action){return PendingIntent.getService(this,request,new Intent(this,RainService.class).setAction(action),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 Notification notification(){String name="自然原声";for(int n=0;n<IDS.length;n++)if(IDS[n].equals(track))name=NAMES[n];boolean active=playing;session.setPlaybackState(new android.media.session.PlaybackState.Builder().setActions(android.media.session.PlaybackState.ACTION_PLAY|android.media.session.PlaybackState.ACTION_PAUSE|android.media.session.PlaybackState.ACTION_PLAY_PAUSE|android.media.session.PlaybackState.ACTION_SKIP_TO_NEXT|android.media.session.PlaybackState.ACTION_SKIP_TO_PREVIOUS|android.media.session.PlaybackState.ACTION_STOP).addCustomAction(new android.media.session.PlaybackState.CustomAction.Builder("timer",timerLabel(),android.R.drawable.ic_lock_idle_alarm).build()).setState(active?android.media.session.PlaybackState.STATE_PLAYING:android.media.session.PlaybackState.STATE_PAUSED,0,active?1:0).build());PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=new Notification.Builder(this,"rain").setSmallIcon(getResources().getIdentifier("ic_leaf","drawable",getPackageName())).setContentTitle("自然入眠").setContentText(name+(active?" · 播放中":" · 已暂停")).setContentIntent(open).setOngoing(active);b.addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,"上一首",serviceAction(2,"previous")).build());b.addAction(new Notification.Action.Builder(active?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,active?"暂停":"播放",serviceAction(3,active?"pause":"play")).build());b.addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,"下一首",serviceAction(4,"next")).build());b.addAction(new Notification.Action.Builder(android.R.drawable.ic_lock_idle_alarm,timerLabel(),serviceAction(5,"timerCycle")).build());return b.setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).build();}
 String timerLabel(){if(minutes==15||minutes==30||minutes==60)return "定时"+minutes+"分";return "定时";}
 // Loading WAV data off the main thread preserves UI responsiveness during sound changes.
 void load(String id){final int token=++generation;loader.submit(()->{try{AudioTrack next=PcmLoop.load(getAssets(),"media/"+id+"-balanced.wav");handler.post(()->{if(destroyed||!playing||token!=generation){next.release();return;}release(retiring);retiring=player;player=next;fadeStarted=SystemClock.elapsedRealtime();player.play();getSystemService(NotificationManager.class).notify(1,notification());});}catch(Exception e){android.util.Log.e("NatureSleep","Audio loading failed",e);handler.post(()->{if(token==generation)stop();});}});}
 final Runnable tick=new Runnable(){public void run(){if(!playing)return;long left=deadline==0?Long.MAX_VALUE:deadline-System.currentTimeMillis();if(left<=0){stop();return;}float fade=Math.min(1,Math.max(0,(SystemClock.elapsedRealtime()-fadeStarted)/2000f));float v=volume*duck*Math.min(1,left/30000f);if(player!=null)player.setVolume(v*fade);if(retiring!=null){retiring.setVolume(v*(1-fade));if(fade>=1){release(retiring);retiring=null;}}handler.postDelayed(this,50);}};
 public int onStartCommand(Intent i,int flags,int id){if(i==null)return START_NOT_STICKY;String action=i.getAction();if("play".equals(action)){play();}else if("track".equals(action)){String name=i.getStringExtra("track");if(validTrack(name)&&!name.equals(track)){track=name;if(playing)load(name);else refreshNotification();}}else if("pause".equals(action))pausePlayback();else if("previous".equals(action))changeTrack(-1);else if("next".equals(action))changeTrack(1);else if("timerCycle".equals(action))cycleTimer();else if("timer".equals(action)){minutes=i.getIntExtra("value",0);deadline=playing&&minutes>0?System.currentTimeMillis()+minutes*60000L:0;if(playing){handler.removeCallbacks(tick);handler.post(tick);}refreshNotification();}else if("mixAudio".equals(action)){mixAudio=i.getBooleanExtra("value",false);getSharedPreferences("playback",0).edit().putBoolean("mixAudio",mixAudio).apply();if(playing&&!requestFocus())pausePlayback();}else if("volume".equals(action))volume=Math.max(0,Math.min(1,(float)i.getDoubleExtra("value",1)));return START_NOT_STICKY;}
 void play(){if(playing)return;startForeground(1,notification());if(!requestFocus()){pausePlayback();return;}playing=true;if(wake!=null&&!wake.isHeld())wake.acquire();if(deadline==0&&minutes>0)deadline=System.currentTimeMillis()+minutes*60000L;load(track);handler.removeCallbacks(tick);handler.post(tick);refreshNotification();}
 boolean requestFocus(){if(mixAudio){manager.abandonAudioFocusRequest(focus);duck=1;return true;}return manager.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;}
 void pausePlayback(){playing=false;deadline=0;minutes=0;generation++;handler.removeCallbacks(tick);release(player);release(retiring);player=null;retiring=null;if(wake!=null&&wake.isHeld())wake.release();if(manager!=null)manager.abandonAudioFocusRequest(focus);if(session!=null&&running)refreshNotification();}
 void changeTrack(int delta){int n=java.util.Arrays.asList(IDS).indexOf(track);track=IDS[(n+delta+IDS.length)%IDS.length];if(playing)load(track);else refreshNotification();}
 void cycleTimer(){int[] values={15,30,60,0};int n=0;while(n<values.length&&values[n]!=minutes)n++;minutes=values[(n+1)%values.length];deadline=playing&&minutes>0?System.currentTimeMillis()+minutes*60000L:0;if(playing){handler.removeCallbacks(tick);handler.post(tick);}refreshNotification();}
 void refreshNotification(){if(session!=null){session.setMetadata(new android.media.MediaMetadata.Builder().putString(android.media.MediaMetadata.METADATA_KEY_TITLE,NAMES[java.util.Arrays.asList(IDS).indexOf(track)]).putString(android.media.MediaMetadata.METADATA_KEY_ARTIST,"自然入眠").build());session.setActive(true);}if(running)try{getSystemService(NotificationManager.class).notify(1,notification());}catch(Exception ignored){}}
 static void release(AudioTrack audio){if(audio!=null){try{audio.stop();}catch(Exception ignored){}audio.release();}}
 void stop(){pausePlayback();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 public void onDestroy(){destroyed=true;pausePlayback();running=false;loader.shutdown();if(session!=null)session.release();super.onDestroy();}
 public IBinder onBind(Intent i){return null;}
}

